		t.Errorf("expected 2, got %d", intResult.Value)
	}
}

func TestLogicalOperators(t *testing.T) {
	input := "true && false;"

	l := lexer.New(input)
	p := parser.New(l)
	program := p.ParseProgram()

	ch := checker.New()
	ch.Check(program)

	c := compiler.New(ch.GlobalScope())
