func (vm *VM) leftShift(left, right object.Object) object.Object {
	l, ok1 := left.(*object.Integer)
	r, ok2 := right.(*object.Integer)
	if ok1 && ok2 && r.Value >= 0 {
		return &object.Integer{Value: l.Value << uint(r.Value)}
