func (vm *VM) index(left, index object.Object) object.Object {
	switch l := left.(type) {
	case *object.Array:
		idx, ok := index.(*object.Integer)
		if ok && idx.Value >= 0 && int(idx.Value) < len(l.Elements) {
			return l.Elements[int(idx.Value)]
		}
		return &object.Null{}

	case *object.Hash:
		key := vm.objectToString(index)
		if val, ok := l.Pairs[key]; ok {
			return val
		}
		return &object.Null{}

	default:
		return &object.Null{}
	}
}

func (vm *VM) len(obj object.Object) int {
	switch o := obj.(type) {
	case *object.String:
		return len(o.Value)
	case *object.Array:
		return len(o.Elements)
	case *object.Hash:
		return len(o.Pairs)
	default:
		return 0
	}
}

func (vm *VM) getType(obj object.Object) string {
	switch obj.(type) {
	case *object.Integer:
		return "int"
	case *object.String:
		return "string"
	case *object.Boolean:
		return "bool"
	case *object.Array:
		return "array"
	case *object.Hash:
		return "hash"
	case *object.Null:
		return "null"
	default:
		return "unknown"
	}
}

