// Test Case 10: Operator Precedence
func TestOperatorPrecedence(t *testing.T) {
	tests := []struct {
		code   string
		expect int64
	}{
		{"2 + 3 * 4;", 14},      // 3 * 4 first
		{"(2 + 3) * 4;", 20},    // 2 + 3 first
		{"10 - 5 - 2;", 3},      // left-to-right
		{"2 ** 3 ** 2;", 512},   // right-to-left
	}

	for _, tt := range tests {
		result, err := evalCode(tt.code)
		if err != nil {
			t.Errorf("code '%s': %v", tt.code, err)
			continue
